    }
    fn binary(self, operation: &str, b: impl Into<Signal>) -> Self {
        Self::raw(format!(
            "{{\"op\":\"binary\",\"operation\":{},\"a\":{},\"b\":{}}}",
            quote(operation),
            self.expression,
            b.into().expression
        ))
    }
